#pragma once

/*
 * Host-side runtime for the code generated by `tools/ppcx translate`
 * (see tools/ppcx/README.md). It owns the flat guest address space, the
 * function registry and the default models of the imported system
 * functions.
 *
 * This C code is original to the BotW-PC project and licensed under MIT.
 */

#include "ppcx_abi.h"

/*
 * Provided by the generated translation unit (build/ppcx/gen.c, a derived
 * work of the user's own game dump; never committed to the repository).
 */
extern const PpcxEntry ppcx_functions[];
extern const unsigned ppcx_function_count;
extern const u32 ppcx_entry;
extern const char *ppcx_import_name(u32 import_index);

/* Allocate the flat guest address space. Safe to call more than once. */
void ppcx_runtime_init(void);

/* Reset the CPU, run the generated entry point and print a run summary. */
int ppcx_run(void);

/* Number of emulated (HLE) system calls performed so far. */
unsigned ppcx_hle_call_count(void);
